ALLOWED = {'read_logs', 'get_status', 'draft_plan'}
MAX_STEPS = 5

def run_loop(proposals):
    audit = []
    for step, action in enumerate(proposals[:MAX_STEPS], start=1):
        if action not in ALLOWED:
            audit.append({'step': step, 'action': action, 'result': 'REJECTED'})
            break
        audit.append({'step': step, 'action': action, 'result': 'SIMULATED'})
        if action == 'draft_plan':
            break
    return audit

print(run_loop(['read_logs', 'get_status', 'delete_cluster']))
